function slashEffect(){const vertices=[];for(let i=0;i<48;i++){const a=i/48*Math.PI,b=(i+1)/48*Math.PI,inner=2.5,ra=inner+.95*Math.pow(Math.sin(a),.6),rb=inner+.95*Math.pow(Math.sin(b),.6),point=(t,r)=>[Math.cos(t)*r,0,Math.sin(t)*r];vertices.push(...point(a,inner),...point(a,ra),...point(b,rb),...point(a,inner),...point(b,rb),...point(b,inner));}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));for(let side=0;side<(swordCombo===3?2:1);side++){const m=new THREE.Mesh(geometry.clone(),new THREE.MeshBasicMaterial({color:swordCombo===3?0xeaffff:0x88f5ff,transparent:true,opacity:.95,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));m.position.copy(player.pos);m.position.y-=.35;m.rotation.set(swordCombo===1?.22:-.15,yaw+Math.PI+side*Math.PI,0);m.userData.effect=true;scene.add(m);slashEffects.push({m,life:.22});}geometry.dispose();}
function swingSword(){if(swordTime>0){swordQueued=true;return;}swordCombo=comboWindow>0?swordCombo%3+1:1;swordDuration=1.5;cooldown=swordDuration;swordTime=swordDuration;swordFrame=0;swordHit=false;swordQueued=false;comboWindow=.85;swordFired(playerAvatar,swordCombo,swordDuration);notify(swordCombo===3?'3타 · 회전베기':`${swordCombo}타 · ${swordCombo===1?'내려베기':'되받아베기'}`);tone(swordCombo===3?95:180,.18,'sawtooth',.07);}
function swordDamage(){const forward=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));let count=0;const radius=[5.3,5.6,6.2][swordCombo-1]||5.3,damage=[85,110,150][swordCombo-1]||85;scene.updateMatrixWorld(true);for(const e of enemies){if(e.hp<=0)continue;const center=e.group.position.clone().add(new THREE.Vector3(0,e.boss?2:e.type==='spider'?.35:1.1,0)),offset=center.sub(player.pos),distance=offset.length();const flat=offset.clone().setY(0).normalize();if(distance>radius+(e.boss?1:0)||(swordCombo!==3&&flat.dot(forward)<-.05))continue;ray.set(player.pos,offset.normalize());ray.far=distance-.1;if(ray.intersectObjects(worldObstacles,false).length)continue;e.hp-=damage;e.hit=.2;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),0x68e9ff,12);count++;}if(count){hitTime=.2;$('hit').style.color='#68e9ff';tone(90,.15,'triangle',.12);}ammo--;}
function beginWave(){wave++;wavePending=false;waveWait=0;bossCount=wave;const count=5+wave*2;for(let i=0;i<count;i++)spawn(false,i%4===0?'sniper':i%4===1?'spider':'trooper');spawn(true);const boss=enemies.at(-1);boss.hp=boss.max=1800+wave*450;notify(`WAVE ${wave} · 일반 적 ${count} + 파괴자`);tone(100,.3,'sawtooth',.06);}
function updateWaves(dt){if(enemies.length)return;if(!wavePending){wavePending=true;waveWait=3;player.hp=Math.min(100,player.hp+20);notify(`WAVE ${wave} 클리어 · 3초 후 다음 웨이브`);}else{waveWait-=dt;if(waveWait<=0)beginWave();}}
