function targetVector(e){return new THREE.Vector3(e.snipeTarget.x,e.snipeTarget.y,e.snipeTarget.z);}
function redLine(start,end,life,opacity){const delta=end.clone().sub(start),m=new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,delta.length(),8),new THREE.MeshBasicMaterial({color:0xff1636,transparent:true,opacity,depthWrite:false}));m.position.copy(start).add(end).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());m.userData.effect=true;scene.add(m);shots.push({m,life});}
function markSniper(e){e.group.rotation.y=Math.atan2(e.snipeTarget.x-e.group.position.x,e.snipeTarget.z-e.group.position.z);animateRobot(e.robot,.25,{aim:1,elevation:Math.atan2(e.snipeTarget.y-e.group.position.y-1.8,Math.hypot(e.snipeTarget.x-e.group.position.x,e.snipeTarget.z-e.group.position.z)),speed:0});e.group.updateMatrixWorld(true);e.snipeStart=e.robot.muzzle.getWorldPosition(new THREE.Vector3());const target=targetVector(e);redLine(e.snipeStart,target,.5,.95);const marker=new THREE.Mesh(new THREE.RingGeometry(.48,.56,24),new THREE.MeshBasicMaterial({color:0xff263b,side:THREE.DoubleSide,transparent:true,opacity:.8}));marker.rotation.x=-Math.PI/2;marker.position.copy(target);marker.position.y=Math.max(.04,target.y-1.65);marker.userData.effect=true;scene.add(marker);shots.push({m:marker,life:.5});tone(900,.08,'sine',.03);}
function fireSniper(e){const start=e.snipeStart||e.robot.muzzle.getWorldPosition(new THREE.Vector3()),target=targetVector(e),delta=target.clone().sub(start),distance=delta.length();ray.set(start,delta.normalize());ray.far=distance+.1;const wall=ray.intersectObjects(worldObstacles,false)[0];const end=wall?wall.point:target;const point=ray.ray.intersectSphere(new THREE.Sphere(player.pos,.65),new THREE.Vector3());if(point&&point.distanceTo(start)<=distance+.1&&(!wall||point.distanceTo(start)<wall.distance))damage(18);redLine(start,end,1.2,1);burst(end,0xff263b,5);robotFired(e.robot);tone(120,.12,'sawtooth',.06);}
