if(import.meta.env.DEV&&new URLSearchParams(location.search).has('enemyCheck')){reset();for(const e of enemies){scene.remove(e.group);disposeRobot(e.robot);}enemies.length=0;for(const [i,type]of ['sniper','spider','boss'].entries()){spawn(type==='boss',type);enemies.at(-1).group.position.set((i-1)*4,0,5);enemies.at(-1).bossAnchor.copy(enemies.at(-1).group.position);}active=true;damageGrace=999;$('overlay').style.display='none';}
